// Is the stack actually ready, or is only n8n awake?
//
// A health check that returns ok:true because the webhook fired tells you
// nothing you needed to know. Everything that can be down here is a separate
// process on a separate port, and the failure that matters is starting a long
// unattended run against a model server that is not loaded.
const targets = [
  ['text',   ($env.DAEMONS_LLM_URL    || $env.DEX_LLM_URL || 'http://host.docker.internal:1234') + '/v1/models'],
  ['vision', ($env.DAEMONS_VISION_URL || $env.MLX_VLM_URL || 'http://host.docker.internal:8890') + '/v1/models'],
  ['image',  ($env.BONSAI_URL || 'http://host.docker.internal:8000') + '/'],
  // /health, not / -- the TTS server is FastAPI and defines no root route,
  // so probing / got a 404 from a server that was up and answering. Measured
  // 2026-09-08: :8880/ -> 404, :8880/health -> 200 with index voice ready.
  ['tts',    ($env.DEXTER_TTS_URL || 'http://host.docker.internal:8880/tts').replace(/\/tts$/, '/health')],
];
const services = {};
for (const [name, url] of targets) {
  const t0 = Date.now();
  try {
    await this.helpers.httpRequest({ method: 'GET', url, timeout: 4000,
                                     json: false, returnFullResponse: true });
    services[name] = { up: true, ms: Date.now() - t0 };
  } catch (e) {
    // A 4xx still proves something is listening; only a transport error is down.
    // n8n's httpRequest does not always carry statusCode or response.status --
    // sometimes the status survives only in the message, and reading just the
    // two structured fields marked a live server as down. Measured: the TTS
    // 404 above arrived as "Request failed with status code 404" and NOTHING
    // else, so the health check called a working service dead.
    const fromMessage = String((e && e.message) || '').match(/status code (\d{3})/);
    const code = (e && (e.statusCode || (e.response && e.response.status)))
      || (fromMessage ? Number(fromMessage[1]) : null);
    services[name] = code ? { up: true, ms: Date.now() - t0, status: code }
                          : { up: false, ms: Date.now() - t0,
                              error: String((e && e.message) || e).slice(0, 120) };
  }
}
const down = Object.keys(services).filter(k => !services[k].up);
return [{ json: {
  ok: down.length === 0,
  // The decide path needs text; look needs vision; sprite needs image. Saying
  // which of those is usable is more actionable than one boolean.
  ready: { decide: services.text.up, look: services.vision.up,
           sprite: services.image.up, speak: services.tts.up },
  services, down, checkedAt: new Date().toISOString(),
} }];
